// TriggerPreFormattedWarning prepares the warning and sends it to the Liquidsoap warnings queue.
func TriggerPreFormattedWarning(cfg *Config, warningFile string, chimeFile string, triggeredBy string) (string, error) {
	outputFile, durationSecs, err := CompilePreFormattedWarning(cfg, warningFile, chimeFile)
	if err != nil {
		return "", err
	}

	displayName := fmt.Sprintf("Aviso Pré-Formatado: %s", filepath.Base(warningFile))
	artistDisplay := "Aviso Imediato"
	if strings.TrimSpace(triggeredBy) != "" {
		artistDisplay = fmt.Sprintf("Aviso Imediato • Disparado por: %s", strings.TrimSpace(triggeredBy))
	}
	LogLocal("WARNING", "[PreWarning] Aviso pré-formatado acionado: '%s' (Duração: %ds, Chime: %s, Operador: %s)", displayName, durationSecs, chimeFile, triggeredBy)

