+// assembleAudioFiles seamlessly concatenates audio files into a single gapless output file
+// without corrupted intermediate metadata headers that could prematurely abort decoding.
+func assembleAudioFiles(inputPaths []string, outputPath string, ext string) error {
+	outFile, err := os.Create(outputPath)
+	if err != nil {
+		return fmt.Errorf("falha ao criar arquivo de saída '%s': %w", outputPath, err)
+	}
+	defer outFile.Close()
+
+	isMP3 := strings.ToLower(ext) == ".mp3" || ext == ""
