"// CompilePreFormattedWarning prepares the warning file, optionally prepending a chime, and returns path and duration.
func CompilePreFormattedWarning(cfg *Config, warningFile string, chimeFile string) (string, int, error) {
	warningPath, err := resolvePreFormattedPath(warningFile)
	if err != nil {
		return "", 0, fmt.Errorf("arquivo de aviso pré-formatado não encontrado: %w", err)
	}

	absWarningFile, err := filepath.Abs(warningPath)
	if err != nil {
		return "", 0, fmt.Errorf("falha ao obter caminho absoluto do aviso: %w", err)
	}

	// Check if we should prepend a chime
	useChimeActual := false
	var absChimeFile string
	if chimeFile != "" {
		chimePath, errChime := resolveChimePath(chimeFile)
		if errChime == nil {
			absChimeFile, err = filepath.Abs(chimePath)
			if err == nil {
				if _, statErr := os.Stat(absChimeFile); statErr == nil {
					useChimeActual = true
				} else {
					LogLocal("WARNING", "[Warning] Chime '%s' resolvido para '%s', mas arquivo não existe no disco", chimeFile, absChimeFile)
				}
			}
		} else {
			LogLocal("WARNING", "[Warning] Chime '%s' solicitado, mas não foi encontrado: %v", chimeFile, errChime)
		}
	}

	ext := strings.ToLower(filepath.Ext(warningFile))
	if ext != ".mp3" && ext != ".wav" {
		ext = ".mp3"
	}

	tempDir := filepath.Join(os.TempDir(), "warnings")
	_ = os.MkdirAll(tempDir, 0755)

	analysis, err := AnalyzeAudioFile(cfg, absWarningFile)"

