"// prepareCleanAudioForLiquidsoap ensures that the audio is decrypted, sanitized of corrupt headers, and saved to a temporary location for Liquidsoap
func prepareCleanAudioForLiquidsoap(filePath string) (string, error) {
	data, err := os.ReadFile(filePath)
	if err != nil {
		return filePath, err
	}
	if len(data) >= 3 && isXORedMP3(data[:3]) {
		dec := make([]byte, len(data))
		for i := range data {
			dec[i] = data[i] ^ 0x53
		}
		data = dec
	}
	cleanFrames := extractRawMP3AudioFrames(data)
	if len(cleanFrames) == 0 {
		cleanFrames = data
	}
	tempDir := filepath.Join(os.TempDir(), "warnings")
	_ = os.MkdirAll(tempDir, 0755)
	cleanPath := filepath.Join(tempDir, fmt.Sprintf("clean_%d_%s", time.Now().UnixNano(), filepath.Base(filePath)))
	if err := os.WriteFile(cleanPath, cleanFrames, 0644); err != nil {
		return filePath, err
	}
	return cleanPath, nil
}

// pushAudioToLiquidsoapQueue pushes an audio file path to Liquidsoap's warnings_queue HTTP endpoint
func pushAudioToLiquidsoapQueue(cfg *Config, filePath string) error {
	cleanPath, errClean := prepareCleanAudioForLiquidsoap(filePath)
	if errClean == nil && cleanPath != "" {
		filePath = cleanPath
	}

	escapedPath := strings.ReplaceAll(filePath, `\`, `/`)
	port := getHarborPort()
	if cfg != nil && cfg.HarborPort != 0 {
		port = cfg.HarborPort
	}
	uri := fmt.Sprintf("http://127.0.0.1:%d/push_warning?path=%s", port, url.QueryEscape(escapedPath))

	client := &http.Client{Timeout: 3 * time.Second}
	resp, err := client.Get(uri)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	bodyBytes, _ := io.ReadAll(resp.Body)
	LogLocal("INFO", "[Warning] Resposta do Liquidsoap: %s", string(bodyBytes))
	return nil
}"

