	// Sort commercials so that those with least spent or oldest play time get scheduled with priority
	type commWithSpent struct {
		comm         activeComm
		alreadySpent int
		lastPlayedAt string
	}
	var commsWithSpent []commWithSpent
	for _, c := range commercials {
		var spent int
		var lastPlayed sql.NullString
		_ = tx.QueryRow(`
			SELECT COUNT(*), MAX(played_at) 
			FROM planned_commercial_slots 
			WHERE play_date = $1 AND commercial_id = $2 AND status IN ('PLAYED', 'QUEUED')`, 
			dateStr, c.ID).Scan(&spent, &lastPlayed)
		commsWithSpent = append(commsWithSpent, commWithSpent{
			comm:         c,
			alreadySpent: spent,
			lastPlayedAt: lastPlayed.String,
		})
	}

	sort.SliceStable(commsWithSpent, func(i, j int) bool {
		if commsWithSpent[i].alreadySpent != commsWithSpent[j].alreadySpent {
			return commsWithSpent[i].alreadySpent < commsWithSpent[j].alreadySpent
		}
		return commsWithSpent[i].lastPlayedAt < commsWithSpent[j].lastPlayedAt
	})

	numComms := len(commsWithSpent)
	for commIdx, item := range commsWithSpent {
		c := item.comm
		alreadySpent := item.alreadySpent
		if c.InsertionsPerDay <= 0 {
			continue
		}"

