"var lastSystemVolume float64 = 1.0
var isSystemMuted bool = false

func GetSystemVolume() (float64, bool) {
	if runtime.GOOS == "linux" {
		out, err := exec.Command("amixer", "sget", "Master").Output()
		if err == nil {
			str := string(out)
			muted := strings.Contains(str, "[off]")
			idx := strings.Index(str, "[")
			if idx != -1 {
				endIdx := strings.Index(str[idx:], "%]")
				if endIdx != -1 {
					pctStr := str[idx+1 : idx+endIdx]
					if val, errParse := strconv.Atoi(pctStr); errParse == nil {
						lastSystemVolume = float64(val) / 100.0
						isSystemMuted = muted
						return lastSystemVolume, isSystemMuted
					}
				}
			}
		}
	}
	return lastSystemVolume, isSystemMuted
}

func SetSystemVolume(level float64, mute bool) error {
	if level < 0.0 {
		level = 0.0
	}
	if level > 1.0 {
		level = 1.0
	}
	lastSystemVolume = level
	isSystemMuted = mute

	if runtime.GOOS == "linux" {
		pct := int(level * 100)
		_ = exec.Command("amixer", "sset", "Master", fmt.Sprintf("%d%%", pct)).Run()
		if mute {
			_ = exec.Command("amixer", "sset", "Master", "mute").Run()
		} else {
			_ = exec.Command("amixer", "sset", "Master", "unmute").Run()
		}
	}
	return nil
}

