"// pushToLiquidsoap sends a track URI to Liquidsoap's commercials queue via harbor
func pushToLiquidsoap(uri string) {
	port := 7000
	if CurrentConfig != nil {
		port = CurrentConfig.HarborPort
	}
	urlStr := fmt.Sprintf("http://127.0.0.1:%d/push_commercial?path=%s", port, url.QueryEscape(uri))
	client := &http.Client{Timeout: 3 * time.Second}
	resp, err := client.Get(urlStr)
	if err != nil {
		LogLocal("ERROR", "[ExternalScheduler] Failed to push item to Liquidsoap: %v", err)
		return
	}
	defer resp.Body.Close()

	bodyBytes, _ := io.ReadAll(resp.Body)
	var respData map[string]interface{}
	if err := json.Unmarshal(bodyBytes, &respData); err == nil {
		if status, ok := respData["status"].(string); ok && status == "success" {
			LogLocal("INFO", "[ExternalScheduler] Successfully pushed item to Liquidsoap: %s", string(bodyBytes))
		} else {
			LogLocal("ERROR", "[ExternalScheduler] Liquidsoap rejected push: %s", string(bodyBytes))
		}
	} else if resp.StatusCode == http.StatusOK {
		LogLocal("INFO", "[ExternalScheduler] Successfully pushed item to Liquidsoap: %s", string(bodyBytes))
	} else {
		LogLocal("ERROR", "[ExternalScheduler] Liquidsoap returned HTTP status %d for push: %s", resp.StatusCode, string(bodyBytes))
	}
}"

